// A failure inside n8n is invisible to the outbox in one specific way: the
// drain sees a non-2xx from the webhook and retries correctly, but if the
// Airtable node fails AFTER the webhook has already responded 200, the outbox
// records a success that never happened. That is the gap this workflow closes.
//
// No lead data in the alert — a lead id and a link, same rule /ops follows.

const e = $input.first().json;

const workflow = e.workflow?.name ?? 'unknown workflow';
const node = e.execution?.lastNodeExecuted ?? 'unknown node';
const message = (e.execution?.error?.message ?? 'no message').slice(0, 300);
const url = e.execution?.url ?? '';

return [{
  json: {
    text: [
      `:rotating_light: LexHive automation failure`,
      `*Workflow:* ${workflow}`,
      `*Node:* ${node}`,
      `*Error:* ${message}`,
      url ? `<${url}|Open execution>` : '',
    ].filter(Boolean).join('\n'),
  },
}];
